const data = $json;

return [
  {
    json: {
      candidate_name: data["Candidate Name"] || "",
      email: data["Email"] || "",
      language: data["Programming Language"] || "",
      difficulty: data["Difficulty"] || "",
      problem_statement: data["Problem Statement"] || "",
      requirements: data["Requirements"] || "",
      constraints: data["Constraints"] || "",
      existing_code: data["Existing Code"] || "",
      submitted_at: new Date().toISOString()
    }
  }
];

const rawOutput = $json.output;

if (!rawOutput) {
  throw new Error("Final Coding Report Agent returned no output.");
}

let text = String(rawOutput).trim();

// Remove markdown code fences if the AI adds them
text = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Find the JSON object
const start = text.indexOf("{");
const end = text.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("No JSON object found in AI response.");
}

const jsonText = text.substring(start, end + 1);

let report;

try {
  report = JSON.parse(jsonText);
} catch (error) {
  throw new Error(
    "AI returned invalid JSON: " + error.message
  );
}

// Basic validation
if (!report.candidate) {
  throw new Error("Missing candidate information.");
}

if (
  typeof report.overall_score !== "number" ||
  report.overall_score < 0 ||
  report.overall_score > 100
) {
  throw new Error("Invalid overall score.");
}

return [
  {
    json: report
  }
];
